-- Migração 28 (schema market, compartilhado): Market Intelligence dentro da Campos Wealth (D-054). Cole no SQL Editor e execute uma vez.
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 19: Market Intelligence inside Campos Wealth (D-054). One shared schema for market data (it is the same for every
-- environment and every office): no personal data. Written and read only by the server with the service role (production
-- deployment), so authenticated and anon have no privilege at all; RLS is forced with no policy (deny by default).
-- Same structure as the original Market Intelligence project, so its history can be copied as is.

create schema if not exists market;
revoke all on schema market from public, anon, authenticated;
grant usage on schema market to service_role;
-- 1. Verified facts: single source of truth for agents 2 and 3.
create table if not exists market.verified_facts (
  id text primary key,
  category text not null check (category in ('MARKET','MACRO','NEWS','CALENDAR','RESEARCH')),
  metric text not null,
  label text not null,
  region text not null,
  value double precision,
  unit text not null,
  reference_period text,
  as_of timestamptz,
  retrieved_at timestamptz not null,
  primary_source text,
  secondary_source text,
  primary_url text,
  secondary_url text,
  verification_status text not null check (verification_status in ('UNVERIFIED','VERIFIED','CONFLICT','REJECTED','UNAVAILABLE')),
  confidence text not null check (confidence in ('HIGH','MEDIUM','LOW','NONE')),
  notes text,
  change_pct double precision,
  previous_value double precision,
  market_status text not null default 'UNKNOWN',
  timezone text not null default 'UTC',
  source_fallback boolean not null default false,
  single_source boolean not null default false,
  is_stale boolean not null default false,
  brief_date date not null,
  run_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists verified_facts_brief_date_idx on market.verified_facts (brief_date);
create index if not exists verified_facts_metric_date_idx on market.verified_facts (metric, brief_date desc);

-- 2. Raw observations: audit trail of what each collector returned.
create table if not exists market.raw_observations (
  id text primary key,
  run_id text not null,
  brief_date date not null,
  "sourceId" text not null,
  category text not null,
  metric text not null,
  value double precision not null,
  unit text not null,
  "referencePeriod" text not null,
  "asOf" timestamptz not null,
  "retrievedAt" timestamptz not null,
  url text not null,
  "previousValue" double precision,
  "changePct" double precision,
  "marketStatus" text,
  notes text
);
create index if not exists raw_observations_brief_date_idx on market.raw_observations (brief_date);

-- 3. News and event clusters (deduplicated events).
create table if not exists market.news_items (
  id text primary key,
  headline text not null,
  original_summary text not null default '',
  published_at timestamptz not null,
  retrieved_at timestamptz not null,
  source text not null,
  source_id text not null,
  url text not null,
  topic text not null,
  region text not null,
  importance real not null,
  market_relevance real not null,
  uhnw_relevance real not null,
  social_relevance real not null,
  verification_status text not null,
  event_cluster_id text,
  brief_date date not null
);
create index if not exists news_items_brief_date_idx on market.news_items (brief_date);
create index if not exists news_items_cluster_idx on market.news_items (event_cluster_id);

create table if not exists market.event_clusters (
  id text primary key,
  title text not null,
  topic text not null,
  region text not null,
  first_published_at timestamptz not null,
  last_published_at timestamptz not null,
  item_ids jsonb not null default '[]',
  sources jsonb not null default '[]',
  importance real not null,
  market_relevance real not null,
  uhnw_relevance real not null,
  social_relevance real not null,
  verification_status text not null,
  brief_date date not null
);
create index if not exists event_clusters_brief_date_idx on market.event_clusters (brief_date);

-- 4. Event engine / editorial calendar.
create table if not exists market.calendar_events (
  id text primary key,
  name text not null,
  category text not null check (category in ('MACRO','MARKET','POLICY','TAX','REGULATION','TECH','CORPORATE','GEOPOLITICS','HOLIDAY','SOCIAL')),
  region text not null,
  date date not null,
  time text,
  timezone text not null,
  source text not null,
  source_url text,
  importance text not null,
  market_relevance text not null,
  audience_relevance text not null,
  content_opportunity text,
  verification_status text not null,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists calendar_events_date_idx on market.calendar_events (date);

-- 5. Research broker.
create table if not exists market.research_requests (
  id text primary key,
  requested_by text not null,
  question text not null,
  metric text,
  priority text not null,
  deadline timestamptz,
  required_sources jsonb not null default '[]',
  status text not null check (status in ('PENDING','IN_PROGRESS','COMPLETED','FAILED','CONFLICT')),
  response jsonb,
  created_at timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists research_requests_status_idx on market.research_requests (status);

-- 6. Observability.
create table if not exists market.agent_runs (
  run_id text primary key,
  parent_run_id text,
  agent text not null,
  job text,
  brief_date date,
  started_at timestamptz not null,
  finished_at timestamptz,
  status text not null,
  items_collected integer not null default 0,
  items_verified integer not null default 0,
  items_rejected integer not null default 0,
  errors jsonb not null default '[]',
  sources jsonb not null default '[]',
  execution_metadata jsonb not null default '{}'
);
create index if not exists agent_runs_started_idx on market.agent_runs (started_at desc);
create index if not exists agent_runs_brief_date_idx on market.agent_runs (brief_date);

-- 7. Intelligence snapshots — append-only history (one row per brief version).
create table if not exists market.intelligence_snapshots (
  id text primary key,
  date date not null,
  version integer not null,
  generated_at timestamptz not null,
  run_id text not null,
  status text not null,
  analysis_mode text not null,
  market_snapshot jsonb not null,
  macro_snapshot jsonb not null,
  news_snapshot jsonb not null,
  what_matters jsonb not null,
  macro_watch jsonb not null,
  insights jsonb not null,
  uhnw_lens jsonb not null,
  content_lab jsonb,
  agenda jsonb not null,
  source_references jsonb not null,
  content_opportunities jsonb not null default '[]',
  qc jsonb not null,
  limitations jsonb not null default '[]',
  unique (date, version)
);
create index if not exists intelligence_snapshots_date_idx on market.intelligence_snapshots (date desc, version desc);

-- History must never be overwritten: block UPDATE and DELETE on snapshots.
create or replace function market.mi_block_snapshot_mutation() returns trigger
language plpgsql set search_path = '' as $$
begin
  raise exception 'intelligence_snapshots is append-only';
end;
$$;
drop trigger if exists intelligence_snapshots_append_only on market.intelligence_snapshots;
create trigger intelligence_snapshots_append_only
  before update or delete on market.intelligence_snapshots
  for each row execute function market.mi_block_snapshot_mutation();

-- 8. Analysis hand-off packets (Claude Code routine mode).
create table if not exists market.analysis_packets (
  id text primary key,
  date date not null,
  run_id text not null,
  created_at timestamptz not null,
  status text not null check (status in ('PENDING','SUBMITTED','EXPIRED')),
  packet jsonb not null,
  submitted_at timestamptz
);
create index if not exists analysis_packets_status_idx on market.analysis_packets (status);

-- 9. Social analytics & strategy.
create table if not exists market.social_posts (
  post_id text primary key,
  published_at timestamptz not null,
  format text not null,
  content_type text not null default 'other',
  topic text not null default 'other',
  caption text not null default '',
  reach double precision not null default 0,
  impressions double precision not null default 0,
  views double precision not null default 0,
  watch_time_s double precision not null default 0,
  avg_watch_time_s double precision not null default 0,
  completion_rate double precision,
  likes double precision not null default 0,
  comments double precision not null default 0,
  shares double precision not null default 0,
  saves double precision not null default 0,
  profile_visits double precision not null default 0,
  follows double precision not null default 0,
  link_clicks double precision not null default 0
);

create table if not exists market.content_opportunities (
  id text primary key,
  event_id text,
  cluster_id text,
  title text not null,
  angle text not null,
  format text not null,
  target_date date not null,
  priority text not null,
  status text not null,
  created_by text not null,
  created_at timestamptz not null default now()
);
create index if not exists content_opportunities_date_idx on market.content_opportunities (target_date);

create table if not exists market.strategy_reports (
  id text primary key,
  week_start date not null,
  generated_at timestamptz not null,
  mode text not null,
  report jsonb not null
);


-- 1. Verified facts: verification method, session normalization, release date, curve instrument.
alter table market.verified_facts
  add column if not exists verification_method text not null default 'unavailable'
    check (verification_method in ('independent_crosscheck','official_crosscheck','official_single','single_source','unofficial_vendor','proxy','derived','unavailable','conflict')),
  add column if not exists session jsonb,
  add column if not exists released_at timestamptz,
  add column if not exists instrument jsonb;

-- 2. Raw observations (audit trail) carry the same session / release / instrument metadata.
alter table market.raw_observations
  add column if not exists session jsonb,
  add column if not exists "releasedAt" timestamptz,
  add column if not exists instrument jsonb;

-- 3. Event clusters: deterministic relevance ranking.
alter table market.event_clusters
  add column if not exists relevance_score real not null default 0,
  add column if not exists relevance_components jsonb not null default '{}',
  add column if not exists hard_override boolean not null default false,
  add column if not exists hard_override_reason text,
  add column if not exists geography text not null default 'GLOBAL',
  add column if not exists domain text not null default 'other',
  add column if not exists metric_target text,
  add column if not exists market_signals jsonb not null default '[]',
  add column if not exists rank_bucket text not null default 'tail' check (rank_bucket in ('top','watchlist','tail'));
create index if not exists event_clusters_rank_idx on market.event_clusters (brief_date, rank_bucket, relevance_score desc);

-- 4. Snapshots: lede (written since round 2, missing from the init migration), curves,
--    watchlist, coverage matrix and the idempotency hash of the submitted analysis.
alter table market.intelligence_snapshots
  add column if not exists lede jsonb,
  add column if not exists rates jsonb,
  add column if not exists watchlist_candidates jsonb not null default '[]',
  add column if not exists coverage_matrix jsonb not null default '[]',
  add column if not exists analysis_hash text;

-- 5. Persistent job lock: one run per job and run key (e.g. MORNING_INTELLIGENCE:2026-10-01).
create table if not exists market.job_leases (
  lease_id text primary key,
  job_name text not null,
  run_key text not null,
  status text not null check (status in ('RUNNING','COMPLETED','FAILED')),
  owner text not null,
  started_at timestamptz not null,
  expires_at timestamptz not null,
  completed_at timestamptz,
  result jsonb,
  unique (job_name, run_key)
);
create index if not exists job_leases_job_idx on market.job_leases (job_name, started_at desc);

alter table market.verified_facts enable row level security;
alter table market.verified_facts force row level security;
alter table market.raw_observations enable row level security;
alter table market.raw_observations force row level security;
alter table market.news_items enable row level security;
alter table market.news_items force row level security;
alter table market.event_clusters enable row level security;
alter table market.event_clusters force row level security;
alter table market.calendar_events enable row level security;
alter table market.calendar_events force row level security;
alter table market.research_requests enable row level security;
alter table market.research_requests force row level security;
alter table market.agent_runs enable row level security;
alter table market.agent_runs force row level security;
alter table market.intelligence_snapshots enable row level security;
alter table market.intelligence_snapshots force row level security;
alter table market.analysis_packets enable row level security;
alter table market.analysis_packets force row level security;
alter table market.social_posts enable row level security;
alter table market.social_posts force row level security;
alter table market.content_opportunities enable row level security;
alter table market.content_opportunities force row level security;
alter table market.strategy_reports enable row level security;
alter table market.strategy_reports force row level security;
alter table market.job_leases enable row level security;
alter table market.job_leases force row level security;
revoke all on all tables in schema market from public, anon, authenticated;
revoke all on all functions in schema market from public, anon, authenticated;
grant all on all tables in schema market to service_role;
alter default privileges in schema market revoke all on tables from public, anon, authenticated;
alter default privileges in schema market revoke all on functions from public, anon, authenticated;
commit;
select 'migração 28 ok' as resultado, (select count(*) from pg_tables where schemaname = 'market') as tabelas_market, (select count(*) from pg_tables where schemaname = 'market' and not rowsecurity) as sem_rls, (select count(*) from information_schema.role_table_grants where table_schema = 'market' and grantee in ('anon','authenticated')) as grants_publicos;
